// ==================================================
// Tool Request Validator
//
// Validates tool execution requests before routing.
//
// Supported tools:
// - get_signins
// - get_endpoint_activity
//
// Requests are treated as untrusted input.
// ==================================================

const request = $json;

const errors = [];


// --------------------------------------------------
// 1. Helpers
// --------------------------------------------------

function requireString(field, value) {
  if (
    typeof value !== "string" ||
    value.trim() === ""
  ) {
    errors.push(
      `${field} must be a non-empty string`
    );
  }
}


function validateTimeRange(
  fieldPrefix,
  timeRange
) {

  if (
    typeof timeRange !== "object" ||
    timeRange === null ||
    Array.isArray(timeRange)
  ) {
    errors.push(
      `${fieldPrefix} must be an object`
    );

    return;
  }


  const allowedFields = [
    "start",
    "end"
  ];


  for (
    const field
    of Object.keys(timeRange)
  ) {

    if (
      !allowedFields.includes(field)
    ) {
      errors.push(
        `${fieldPrefix}.${field} is not allowed`
      );
    }
  }


  if (
    typeof timeRange.start !== "string" ||
    Number.isNaN(
      Date.parse(timeRange.start)
    )
  ) {
    errors.push(
      `${fieldPrefix}.start must be a valid ISO 8601 timestamp`
    );
  }


  if (
    typeof timeRange.end !== "string" ||
    Number.isNaN(
      Date.parse(timeRange.end)
    )
  ) {
    errors.push(
      `${fieldPrefix}.end must be a valid ISO 8601 timestamp`
    );
  }


  if (
    typeof timeRange.start === "string" &&
    typeof timeRange.end === "string" &&
    !Number.isNaN(
      Date.parse(timeRange.start)
    ) &&
    !Number.isNaN(
      Date.parse(timeRange.end)
    ) &&
    Date.parse(timeRange.start) >
      Date.parse(timeRange.end)
  ) {
    errors.push(
      `${fieldPrefix}.start must be before or equal to end`
    );
  }
}


// --------------------------------------------------
// 2. Basic request validation
// --------------------------------------------------

requireString(
  "alert_id",
  request.alert_id
);

requireString(
  "step_id",
  request.step_id
);

requireString(
  "tool",
  request.tool
);


if (
  typeof request.step_id === "string" &&
  !/^step-[0-9]+$/.test(
    request.step_id
  )
) {
  errors.push(
    "step_id must match the format step-N"
  );
}


// --------------------------------------------------
// 3. Parameters object
// --------------------------------------------------

if (
  typeof request.parameters !== "object" ||
  request.parameters === null ||
  Array.isArray(request.parameters)
) {
  errors.push(
    "parameters must be an object"
  );
}


// --------------------------------------------------
// 4. Tool policies
// --------------------------------------------------

const toolPolicies = {

  get_signins: {
    requiredParameters: [
      "user"
    ],

    allowedParameters: [
      "user",
      "time_range",
      "limit"
    ]
  },


  get_endpoint_activity: {
    requiredParameters: [
      "host"
    ],

    allowedParameters: [
      "host",
      "time_range",
      "limit"
    ]
  }

};


// --------------------------------------------------
// 5. Tool allowlist
// --------------------------------------------------

if (
  typeof request.tool === "string" &&
  !Object.prototype.hasOwnProperty.call(
    toolPolicies,
    request.tool
  )
) {
  errors.push(
    `tool '${request.tool}' is not supported`
  );
}


// --------------------------------------------------
// 6. Generic tool parameter validation
// --------------------------------------------------

if (
  typeof request.tool === "string" &&
  Object.prototype.hasOwnProperty.call(
    toolPolicies,
    request.tool
  ) &&
  typeof request.parameters === "object" &&
  request.parameters !== null &&
  !Array.isArray(request.parameters)
) {

  const policy =
    toolPolicies[request.tool];


  // Required parameters

  for (
    const parameter
    of policy.requiredParameters
  ) {

    if (
      !Object.prototype.hasOwnProperty.call(
        request.parameters,
        parameter
      )
    ) {
      errors.push(
        `parameters.${parameter} is required for ${request.tool}`
      );
    }
  }


  // Unexpected parameters

  for (
    const parameter
    of Object.keys(
      request.parameters
    )
  ) {

    if (
      !policy.allowedParameters.includes(
        parameter
      )
    ) {
      errors.push(
        `parameters.${parameter} is not allowed for ${request.tool}`
      );
    }
  }
}


// --------------------------------------------------
// 7. get_signins validation
// --------------------------------------------------

if (
  request.tool === "get_signins" &&
  typeof request.parameters === "object" &&
  request.parameters !== null &&
  !Array.isArray(request.parameters)
) {

  const {
    user,
    time_range,
    limit
  } = request.parameters;


  if (
    typeof user !== "string" ||
    user.trim() === ""
  ) {
    errors.push(
      "parameters.user must be a non-empty string"
    );
  }


  if (
    typeof user === "string" &&
    user.length > 320
  ) {
    errors.push(
      "parameters.user must not exceed 320 characters"
    );
  }


  if (limit !== undefined) {

    if (
      !Number.isInteger(limit) ||
      limit < 1 ||
      limit > 500
    ) {
      errors.push(
        "parameters.limit must be an integer between 1 and 500"
      );
    }
  }


  if (time_range !== undefined) {
    validateTimeRange(
      "parameters.time_range",
      time_range
    );
  }
}


// --------------------------------------------------
// 8. get_endpoint_activity validation
// --------------------------------------------------

if (
  request.tool ===
    "get_endpoint_activity" &&
  typeof request.parameters === "object" &&
  request.parameters !== null &&
  !Array.isArray(request.parameters)
) {

  const {
    host,
    time_range,
    limit
  } = request.parameters;


  if (
    typeof host !== "string" ||
    host.trim() === ""
  ) {
    errors.push(
      "parameters.host must be a non-empty string"
    );
  }


  if (
    typeof host === "string" &&
    host.length > 255
  ) {
    errors.push(
      "parameters.host must not exceed 255 characters"
    );
  }


  if (limit !== undefined) {

    if (
      !Number.isInteger(limit) ||
      limit < 1 ||
      limit > 500
    ) {
      errors.push(
        "parameters.limit must be an integer between 1 and 500"
      );
    }
  }


  if (time_range !== undefined) {
    validateTimeRange(
      "parameters.time_range",
      time_range
    );
  }
}


// --------------------------------------------------
// 9. Controlled validation output
// --------------------------------------------------

return [
  {
    json: {
      valid:
        errors.length === 0,

      errors,

      request
    }
  }
];

const validationResult = $json;

return [
  {
    json: {
      status: "rejected",

      reason:
        "tool_request_validation_failed",

      errors:
        validationResult.errors || [],

      request:
        validationResult.request || null
    }
  }
];

const validationResult = $json;

if (validationResult.valid !== true) {
  throw new Error(
    "Validated Tool Request received an invalid request"
  );
}

return [
  {
    json: validationResult.request
  }
];

// ==================================================
// get_signins Mock Connector
//
// Simulates a security data source.
//
// No real API call is performed.
// ==================================================

const request = $json;

const parameters =
  request.parameters || {};

const user =
  parameters.user;

const timeRange =
  parameters.time_range || null;

const limit =
  parameters.limit || 100;


// --------------------------------------------------
// Simulated provider events
// --------------------------------------------------

const simulatedEvents = [

  {
    timestamp:
      "2026-08-23T17:20:00Z",

    user:
      "john.doe@example.com",

    source_ip:
      "185.220.101.20",

    status:
      "success",

    authentication_method:
      "MFA",

    application:
      "Microsoft 365",

    device:
      "WIN11-LAPTOP-01",

    location: {
      country:
        "Spain",

      city:
        "Madrid"
    }
  },


  {
    timestamp:
      "2026-08-23T17:42:00Z",

    user:
      "john.doe@example.com",

    source_ip:
      "91.198.174.20",

    status:
      "success",

    authentication_method:
      "MFA",

    application:
      "Microsoft 365",

    device:
      null,

    location: {
      country:
        "Netherlands",

      city:
        "Amsterdam"
    }
  }

];


// --------------------------------------------------
// Filter by requested user
// --------------------------------------------------

let events =
  simulatedEvents.filter(
    event =>
      event.user === user
  );


// --------------------------------------------------
// Optional time range
// --------------------------------------------------

if (timeRange) {

  const start =
    Date.parse(timeRange.start);

  const end =
    Date.parse(timeRange.end);

  events =
    events.filter(event => {

      const timestamp =
        Date.parse(event.timestamp);

      return (
        timestamp >= start &&
        timestamp <= end
      );
    });
}


// --------------------------------------------------
// Apply limit
// --------------------------------------------------

events =
  events.slice(0, limit);


// --------------------------------------------------
// Canonical tool result
// --------------------------------------------------

return [
  {
    json: {
      tool:
        "get_signins",

      tool_version:
        "1.0",

      status:
        "success",

      query: {
        user,
        time_range:
          timeRange
      },

      result_count:
        events.length,

      events,

      error:
        null
    }
  }
];

// ==================================================
// get_signins Output Validator
//
// Deterministically validates the canonical output
// produced by the get_signins connector.
// ==================================================

const result = $json;

const errors = [];


// --------------------------------------------------
// Helpers
// --------------------------------------------------

function requireString(field, value) {
  if (
    typeof value !== "string" ||
    value.trim() === ""
  ) {
    errors.push(
      `${field} must be a non-empty string`
    );
  }
}


function validDate(value) {
  return (
    typeof value === "string" &&
    !Number.isNaN(Date.parse(value))
  );
}


// --------------------------------------------------
// Top-level validation
// --------------------------------------------------

if (result.tool !== "get_signins") {
  errors.push(
    "tool must be 'get_signins'"
  );
}


if (result.tool_version !== "1.0") {
  errors.push(
    "tool_version must be '1.0'"
  );
}


const validStatuses = [
  "success",
  "partial",
  "error"
];

if (
  !validStatuses.includes(
    result.status
  )
) {
  errors.push(
    "status contains an invalid value"
  );
}


// --------------------------------------------------
// Query validation
// --------------------------------------------------

if (
  typeof result.query !== "object" ||
  result.query === null ||
  Array.isArray(result.query)
) {
  errors.push(
    "query must be an object"
  );
} else {

  requireString(
    "query.user",
    result.query.user
  );


  if (
    result.query.time_range !== null &&
    result.query.time_range !== undefined
  ) {

    if (
      typeof result.query.time_range !== "object" ||
      Array.isArray(result.query.time_range)
    ) {
      errors.push(
        "query.time_range must be an object or null"
      );
    } else {

      if (
        !validDate(
          result.query.time_range.start
        )
      ) {
        errors.push(
          "query.time_range.start must be a valid timestamp"
        );
      }

      if (
        !validDate(
          result.query.time_range.end
        )
      ) {
        errors.push(
          "query.time_range.end must be a valid timestamp"
        );
      }
    }
  }
}


// --------------------------------------------------
// result_count
// --------------------------------------------------

if (
  !Number.isInteger(
    result.result_count
  ) ||
  result.result_count < 0
) {
  errors.push(
    "result_count must be a non-negative integer"
  );
}


// --------------------------------------------------
// events
// --------------------------------------------------

if (!Array.isArray(result.events)) {

  errors.push(
    "events must be an array"
  );

} else {

  if (
    Number.isInteger(result.result_count) &&
    result.result_count !==
      result.events.length
  ) {
    errors.push(
      "result_count does not match events.length"
    );
  }


  const validEventStatuses = [
    "success",
    "failure",
    "unknown"
  ];


  result.events.forEach(
    (event, index) => {

      const prefix =
        `events[${index}]`;


      if (
        typeof event !== "object" ||
        event === null ||
        Array.isArray(event)
      ) {
        errors.push(
          `${prefix} must be an object`
        );

        return;
      }


      if (
        !validDate(
          event.timestamp
        )
      ) {
        errors.push(
          `${prefix}.timestamp must be a valid timestamp`
        );
      }


      requireString(
        `${prefix}.user`,
        event.user
      );


      if (
        event.source_ip !== null &&
        typeof event.source_ip !== "string"
      ) {
        errors.push(
          `${prefix}.source_ip must be a string or null`
        );
      }


      if (
        !validEventStatuses.includes(
          event.status
        )
      ) {
        errors.push(
          `${prefix}.status contains an invalid value`
        );
      }


      if (
        event.authentication_method !== null &&
        event.authentication_method !== undefined &&
        typeof event.authentication_method !== "string"
      ) {
        errors.push(
          `${prefix}.authentication_method must be a string or null`
        );
      }


      if (
        event.application !== null &&
        event.application !== undefined &&
        typeof event.application !== "string"
      ) {
        errors.push(
          `${prefix}.application must be a string or null`
        );
      }


      if (
        event.device !== null &&
        event.device !== undefined &&
        typeof event.device !== "string"
      ) {
        errors.push(
          `${prefix}.device must be a string or null`
        );
      }


      if (
        event.location !== null &&
        event.location !== undefined
      ) {

        if (
          typeof event.location !== "object" ||
          Array.isArray(event.location)
        ) {
          errors.push(
            `${prefix}.location must be an object or null`
          );
        } else {

          if (
            event.location.country !== null &&
            event.location.country !== undefined &&
            typeof event.location.country !== "string"
          ) {
            errors.push(
              `${prefix}.location.country must be a string or null`
            );
          }


          if (
            event.location.city !== null &&
            event.location.city !== undefined &&
            typeof event.location.city !== "string"
          ) {
            errors.push(
              `${prefix}.location.city must be a string or null`
            );
          }
        }
      }
    }
  );
}


// --------------------------------------------------
// error
// --------------------------------------------------

if (
  result.error !== null &&
  result.error !== undefined
) {

  if (
    typeof result.error !== "object" ||
    Array.isArray(result.error)
  ) {
    errors.push(
      "error must be an object or null"
    );
  } else {

    requireString(
      "error.code",
      result.error.code
    );

    requireString(
      "error.message",
      result.error.message
    );
  }
}


// --------------------------------------------------
// Reject invalid connector output
// --------------------------------------------------

if (errors.length > 0) {
  throw new Error(
    `get_signins output validation failed: ${errors.join("; ")}`
  );
}


// --------------------------------------------------
// Canonical result
// --------------------------------------------------

return [
  {
    json: result
  }
];

