// ==================================================
// get_endpoint_activity Mock Connector
//
// Simulates endpoint telemetry.
//
// No real EDR/XDR API is queried.
// ==================================================

const request = $json;

const parameters =
  request.parameters || {};

const host =
  parameters.host;

const timeRange =
  parameters.time_range || null;

const limit =
  parameters.limit || 100;


// --------------------------------------------------
// 1. Simulated endpoint telemetry
// --------------------------------------------------

const simulatedEvents = [

  {
    timestamp:
      "2026-08-23T17:25:00Z",

    host:
      "WIN11-LAPTOP-01",

    event_type:
      "user_logon",

    severity:
      "informational",

    user:
      "john.doe@example.com",

    process:
      null,

    network:
      null
  },


  {
    timestamp:
      "2026-08-23T17:36:00Z",

    host:
      "WIN11-LAPTOP-01",

    event_type:
      "process_execution",

    severity:
      "medium",

    user:
      "john.doe@example.com",

    process: {
      name:
        "powershell.exe",

      command_line:
        "powershell.exe -NoProfile -Command Get-Process",

      parent_process:
        "explorer.exe"
    },

    network:
      null
  },


  {
    timestamp:
      "2026-08-23T17:39:00Z",

    host:
      "WIN11-LAPTOP-01",

    event_type:
      "network_connection",

    severity:
      "low",

    user:
      "john.doe@example.com",

    process: {
      name:
        "msedge.exe",

      command_line:
        null,

      parent_process:
        "explorer.exe"
    },

    network: {
      destination_ip:
        "20.190.128.25",

      destination_port:
        443
    }
  }

];


// --------------------------------------------------
// 2. Filter by requested host
// --------------------------------------------------

let events =
  simulatedEvents.filter(
    event =>
      event.host === host
  );


// --------------------------------------------------
// 3. Optional time range
// --------------------------------------------------

if (timeRange) {

  const start =
    Date.parse(
      timeRange.start
    );

  const end =
    Date.parse(
      timeRange.end
    );


  events =
    events.filter(
      event => {

        const timestamp =
          Date.parse(
            event.timestamp
          );

        return (
          timestamp >= start &&
          timestamp <= end
        );
      }
    );
}


// --------------------------------------------------
// 4. Apply limit
// --------------------------------------------------

events =
  events.slice(
    0,
    limit
  );


// --------------------------------------------------
// 5. Canonical tool result
// --------------------------------------------------

return [
  {
    json: {
      tool:
        "get_endpoint_activity",

      tool_version:
        "1.0",

      status:
        "success",

      query: {
        host,

        time_range:
          timeRange
      },

      result_count:
        events.length,

      events,

      error:
        null
    }
  }
];

// ==================================================
// get_endpoint_activity Output Validator
//
// Deterministically validates endpoint telemetry.
// ==================================================

const result = $json;

const errors = [];


// --------------------------------------------------
// Helpers
// --------------------------------------------------

function requireString(
  field,
  value
) {

  if (
    typeof value !== "string" ||
    value.trim() === ""
  ) {
    errors.push(
      `${field} must be a non-empty string`
    );
  }
}


function validDate(
  value
) {

  return (
    typeof value === "string" &&
    !Number.isNaN(
      Date.parse(value)
    )
  );
}


// --------------------------------------------------
// 1. Tool metadata
// --------------------------------------------------

if (
  result.tool !==
    "get_endpoint_activity"
) {
  errors.push(
    "tool must be 'get_endpoint_activity'"
  );
}


if (
  result.tool_version !== "1.0"
) {
  errors.push(
    "tool_version must be '1.0'"
  );
}


const validStatuses = [
  "success",
  "partial",
  "error"
];


if (
  !validStatuses.includes(
    result.status
  )
) {
  errors.push(
    "status contains an invalid value"
  );
}


// --------------------------------------------------
// 2. Query
// --------------------------------------------------

if (
  typeof result.query !== "object" ||
  result.query === null ||
  Array.isArray(result.query)
) {

  errors.push(
    "query must be an object"
  );

} else {

  requireString(
    "query.host",
    result.query.host
  );


  if (
    result.query.time_range !== null &&
    result.query.time_range !== undefined
  ) {

    if (
      typeof result.query.time_range !== "object" ||
      result.query.time_range === null ||
      Array.isArray(
        result.query.time_range
      )
    ) {

      errors.push(
        "query.time_range must be an object or null"
      );

    } else {

      if (
        !validDate(
          result.query.time_range.start
        )
      ) {
        errors.push(
          "query.time_range.start must be a valid timestamp"
        );
      }


      if (
        !validDate(
          result.query.time_range.end
        )
      ) {
        errors.push(
          "query.time_range.end must be a valid timestamp"
        );
      }
    }
  }
}


// --------------------------------------------------
// 3. result_count
// --------------------------------------------------

if (
  !Number.isInteger(
    result.result_count
  ) ||
  result.result_count < 0
) {
  errors.push(
    "result_count must be a non-negative integer"
  );
}


// --------------------------------------------------
// 4. Events
// --------------------------------------------------

if (
  !Array.isArray(
    result.events
  )
) {

  errors.push(
    "events must be an array"
  );

} else {

  if (
    Number.isInteger(
      result.result_count
    ) &&
    result.result_count !==
      result.events.length
  ) {
    errors.push(
      "result_count does not match events.length"
    );
  }


  const validSeverities = [
    "informational",
    "low",
    "medium",
    "high",
    "critical",
    "unknown"
  ];


  result.events.forEach(
    (event, index) => {

      const prefix =
        `events[${index}]`;


      if (
        typeof event !== "object" ||
        event === null ||
        Array.isArray(event)
      ) {

        errors.push(
          `${prefix} must be an object`
        );

        return;
      }


      // Timestamp

      if (
        !validDate(
          event.timestamp
        )
      ) {
        errors.push(
          `${prefix}.timestamp must be a valid timestamp`
        );
      }


      // Host

      requireString(
        `${prefix}.host`,
        event.host
      );


      // Event type

      requireString(
        `${prefix}.event_type`,
        event.event_type
      );


      // Severity

      if (
        !validSeverities.includes(
          event.severity
        )
      ) {
        errors.push(
          `${prefix}.severity contains an invalid value`
        );
      }


      // User

      if (
        event.user !== null &&
        event.user !== undefined &&
        typeof event.user !== "string"
      ) {
        errors.push(
          `${prefix}.user must be a string or null`
        );
      }


      // Process

      if (
        event.process !== null &&
        event.process !== undefined
      ) {

        if (
          typeof event.process !== "object" ||
          event.process === null ||
          Array.isArray(
            event.process
          )
        ) {

          errors.push(
            `${prefix}.process must be an object or null`
          );

        } else {

          const processFields = [
            "name",
            "command_line",
            "parent_process"
          ];


          for (
            const field
            of processFields
          ) {

            if (
              event.process[field] !== null &&
              event.process[field] !== undefined &&
              typeof event.process[field] !== "string"
            ) {
              errors.push(
                `${prefix}.process.${field} must be a string or null`
              );
            }
          }
        }
      }


      // Network

      if (
        event.network !== null &&
        event.network !== undefined
      ) {

        if (
          typeof event.network !== "object" ||
          event.network === null ||
          Array.isArray(
            event.network
          )
        ) {

          errors.push(
            `${prefix}.network must be an object or null`
          );

        } else {

          if (
            event.network.destination_ip !== null &&
            event.network.destination_ip !== undefined &&
            typeof event.network.destination_ip !== "string"
          ) {
            errors.push(
              `${prefix}.network.destination_ip must be a string or null`
            );
          }


          if (
            event.network.destination_port !== null &&
            event.network.destination_port !== undefined &&
            !Number.isInteger(
              event.network.destination_port
            )
          ) {
            errors.push(
              `${prefix}.network.destination_port must be an integer or null`
            );
          }
        }
      }
    }
  );
}


// --------------------------------------------------
// 5. Error object
// --------------------------------------------------

if (
  result.error !== null &&
  result.error !== undefined
) {

  if (
    typeof result.error !== "object" ||
    result.error === null ||
    Array.isArray(
      result.error
    )
  ) {

    errors.push(
      "error must be an object or null"
    );

  } else {

    requireString(
      "error.code",
      result.error.code
    );

    requireString(
      "error.message",
      result.error.message
    );
  }
}


// --------------------------------------------------
// 6. Reject corrupt connector output
// --------------------------------------------------

if (
  errors.length > 0
) {
  throw new Error(
    `get_endpoint_activity output validation failed: ${errors.join("; ")}`
  );
}


// --------------------------------------------------
// 7. Return validated connector result
// --------------------------------------------------

return [
  {
    json: result
  }
];
